// ELEMENTS (sobre o vídeo, fundo transparente):
// 1. Véu navy em gradiente no fundo do ecrã
// 2. Eyebrow (filete ciano + texto)
// 3. Pílulas de vidro navy empilhadas, cada uma com ícone em traço num círculo (ciano; coral e riscado
//    quando cross) e texto, a entrar nos tempos da voz
//    items: [{ icon: loja|relogio|local|calendario|check, text, at, cross? }]
import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY_RGB = "14,22,38";
const CYAN = "#05B8E6";
const CORAL = "#F06052";
const WHITE = "#F4F1EA";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(1.6));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const ICONS: Record<string, string> = {
  loja: "M8 20 L12 10 H36 L40 20 Z M10 20 V38 H38 V20 M20 38 V28 H28 V38",
  relogio: "M24 10 A14 14 0 1 1 23.99 10 M24 16 V24 L30 28",
  local: "M24 40 C24 40 12 29 12 20 A12 12 0 0 1 36 20 C36 29 24 40 24 40 Z M24 15 A5 5 0 1 0 24.01 15",
  calendario: "M10 14 H38 V38 H10 Z M10 21 H38 M17 10 V17 M31 10 V17 M17 28 H21 M27 28 H31",
  check: "M12 25 L20 33 L36 15",
};

type Item = { icon?: string; text?: string; at?: number; cross?: boolean };

const IadChipsIcones: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const eyebrow = String(p.eyebrow ?? anim.text ?? "").trim();
  const items = (Array.isArray(p.items) ? (p.items as Item[]) : []).slice(0, 5);

  const show = (delay: number, len = 0.6, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });

  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, height: "58%", background: `linear-gradient(0deg, rgba(${NAVY_RGB},0.88) 0%, rgba(${NAVY_RGB},0.55) 55%, rgba(${NAVY_RGB},0) 100%)`, opacity: show(0, 0.6) }} />
      <div style={{ position: "absolute", left: 80 * u, right: 80 * u, bottom: 230 * u, display: "flex", flexDirection: "column", gap: 22 * u, alignItems: "flex-start" }}>
        {eyebrow ? (
          <div style={{ display: "flex", alignItems: "center", gap: 18 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 28 * u, letterSpacing: "0.3em", textTransform: "uppercase", color: WHITE, marginBottom: 8 * u, opacity: show(0.1) }}>
            <div style={{ width: 56 * u * show(0.1, 0.8), height: 3 * u, background: CYAN }} />
            {eyebrow}
          </div>
        ) : null}
        {items.map((it, i) => {
          const at = Number.isFinite(Number(it.at)) ? Number(it.at) : 0.4 + i * 0.8;
          const k = show(at, 0.5, BACK);
          const col = it.cross ? CORAL : CYAN;
          return (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 24 * u, background: `rgba(${NAVY_RGB},0.78)`, backdropFilter: `blur(${10 * u}px)`, border: `${2 * u}px solid rgba(244,241,234,0.18)`, borderRadius: 999, padding: `${12 * u}px ${36 * u}px ${12 * u}px ${12 * u}px`, opacity: Math.min(1, k * 1.5), transform: `translateX(${(1 - k) * -60 * u}px) scale(${0.9 + 0.1 * k})`, boxShadow: "0 12px 30px rgba(0,0,0,0.35)" }}>
              <div style={{ position: "relative", width: 84 * u, height: 84 * u, borderRadius: "50%", border: `${3 * u}px solid ${col}`, display: "flex", alignItems: "center", justifyContent: "center" }}>
                <svg width={50 * u} height={50 * u} viewBox="0 0 48 48">
                  <path d={ICONS[String(it.icon ?? "check")] ?? ICONS.check} fill="none" stroke={WHITE} strokeWidth={2.8} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - show(at + 0.15, 0.6)} />
                  {it.cross ? <path d="M8 8 L40 40" stroke={CORAL} strokeWidth={4} strokeLinecap="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - show(at + 0.6, 0.35)} /> : null}
                </svg>
              </div>
              <div style={{ fontFamily: FONTS.display, fontWeight: 500, fontSize: 56 * u, lineHeight: 1.05, color: WHITE }}>{it.text}</div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default IadChipsIcones;
